  VALUES ?graph {
    <urn:graphragprov:unit:u_7a2b9533bdcf92e5>
    <urn:graphragprov:unit:u_ce5e41a1456688a9>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
